<div class="premium-pagination"><ul class="pagination premium-pagination-list m-0"><li class="page-item {{ $currentPage === 1 ? 'disabled' : '' }}"><a class="page-link" href="{{ $currentPage > 1 ? $paginator->url($currentPage - 1) : '#' }}"><i class="ti ti-chevron-left icon icon-1"></i></a></li>@foreach($pages as $page)@if($page === 'ellipsis')<li class="premium-pagination-ellipsis" aria-hidden="true">…</li>@else<li class="page-item {{ $page === $currentPage ? 'active' : '' }}"><a class="page-link" href="{{ $paginator->url($page) }}">{{ $page }}</a></li>@endif @endforeach<li class="page-item {{ $currentPage === $lastPage ? 'disabled' : '' }}"><a class="page-link" href="{{ $currentPage < $lastPage ? $paginator->url($currentPage + 1) : '#' }}"><i class="ti ti-chevron-right icon icon-1"></i></a></li></ul><p class="premium-pagination-info m-0">Showing <strong>{{ $paginator->firstItem() ?? 0 }} to {{ $paginator->lastItem() ?? 0 }}</strong> of <strong>{{ $paginator->total() }} entries</strong></p><div class="premium-pagination-controls"><label class="premium-pagination-select"><select class="form-select form-select-sm" onchange="const u=new URL(window.location.href);u.searchParams.set('per_page',this.value);u.searchParams.set('page',1);window.location=u"><option value="10" @selected($paginator->perPage()==10)>10 / page</option><option value="25" @selected($paginator->perPage()==25)>25 / page</option><option value="50" @selected($paginator->perPage()==50)>50 / page</option><option value="100" @selected($paginator->perPage()==100)>100 / page</option></select></label><label class="premium-pagination-goto"><span>Go to</span><input type="number" class="form-control form-control-sm" min="1" max="{{ $lastPage }}" value="{{ $currentPage }}" onchange="const u=new URL(window.location.href);u.searchParams.set('page',Math.min({{ $lastPage }},Math.max(1,parseInt(this.value)||1)));window.location=u"><span>Page</span></label></div></div>
